#define SATOSHI     100000000ULL

void sha256(const unsigned char *d, size_t n, unsigned char *md) { SHA256(d, n, md); }

static uint64_t parse_amount(const char *str) {
    char *dot = strchr(str, '.'); if (!dot) return strtoull(str, NULL, 10) * SATOSHI;
    uint64_t whole = strtoull(str, NULL, 10); char frac_str[16] = {0}; strncpy(frac_str, dot + 1, 15);
    int frac_len = strlen(frac_str); for (int i = frac_len; i < 8; i++) strcat(frac_str, "0"); frac_str[8] = '\0';
    return whole * SATOSHI + strtoull(frac_str, NULL, 10);
}

