#define WORDLIST_SIZE (sizeof(wordlist)/sizeof(wordlist[0]))
static int is_valid_word(const char *w){for(int i=0;i<(int)WORDLIST_SIZE;i++)if(strcmp(wordlist[i],w)==0)return 1;return 0;}
void generate_passphrase(char *pp,size_t l){unsigned char e[16];RAND_bytes(e,16);pp[0]=0;for(int i=0;i<12;i++){int idx=e[i]%WORDLIST_SIZE;strcat(pp,wordlist[idx]);if(i<11)strcat(pp," ");}}
int create_wallet(const char *fn){unsigned char pk[32],pub[65];char a[65],pp[512];generate_passphrase(pp,sizeof(pp));unsigned char sd[32];sha256((unsigned char*)pp,strlen(pp),sd);memcpy(pk,sd,32);EC_KEY *k=EC_KEY_new_by_curve_name(NID_X9_62_prime256v1);BIGNUM *bn=BN_bin2bn(pk,32,NULL);EC_KEY_set_private_key(k,bn);const EC_GROUP *g=EC_KEY_get0_group(k);EC_POINT *pt=EC_POINT_new(g);EC_POINT_mul(g,pt,bn,NULL,NULL,NULL);EC_POINT_point2oct(g,pt,POINT_CONVERSION_UNCOMPRESSED,pub,65,NULL);unsigned char sh[32];sha256(pub,65,sh);strcpy(a,"BYTE");for(int i=0;i<30;i++)sprintf(a+4+i*2,"%02x",sh[i]);a[64]=0;FILE *f=fopen(fn,"wb");if(!f){BN_free(bn);EC_POINT_free(pt);EC_KEY_free(k);return 0;}fwrite(pk,1,32,f);fwrite(pub,1,65,f);fwrite(a,1,65,f);fclose(f);printf("\n" CLR_GREEN "  Carteira criada!\n" CLR_RESET);printf(CLR_GRAY "  Endereco: " CLR_CYAN "%s\n" CLR_RESET,a);printf(CLR_GRAY "  Passphrase: " CLR_YELLOW "%s\n" CLR_RESET,pp);BN_free(bn);EC_POINT_free(pt);EC_KEY_free(k);return 1;}
int restore_wallet(const char *fn){char w[12][32],pp[512]={0};printf("\n  Restaurar\n");for(int i=0;i<12;i++){printf("  %2d: ",i+1);fflush(stdout);if(!fgets(w[i],sizeof(w[i]),stdin))return 0;w[i][strcspn(w[i],"\r\n")]=0;if(!is_valid_word(w[i])){printf("  '%s' invalida!\n",w[i]);return 0;}}for(int i=0;i<12;i++){strcat(pp,w[i]);if(i<11)strcat(pp," ");}unsigned char pk[32],pub[65];char a[65];unsigned char sd[32];sha256((unsigned char*)pp,strlen(pp),sd);memcpy(pk,sd,32);EC_KEY *k=EC_KEY_new_by_curve_name(NID_X9_62_prime256v1);BIGNUM *bn=BN_bin2bn(pk,32,NULL);EC_KEY_set_private_key(k,bn);const EC_GROUP *g=EC_KEY_get0_group(k);EC_POINT *pt=EC_POINT_new(g);EC_POINT_mul(g,pt,bn,NULL,NULL,NULL);EC_POINT_point2oct(g,pt,POINT_CONVERSION_UNCOMPRESSED,pub,65,NULL);unsigned char sh[32];sha256(pub,65,sh);strcpy(a,"BYTE");for(int i=0;i<30;i++)sprintf(a+4+i*2,"%02x",sh[i]);a[64]=0;FILE *f=fopen(fn,"wb");if(!f){BN_free(bn);EC_POINT_free(pt);EC_KEY_free(k);return 0;}fwrite(pk,1,32,f);fwrite(pub,1,65,f);fwrite(a,1,65,f);fclose(f);printf("\n  Restaurada! %s\n",a);BN_free(bn);EC_POINT_free(pt);EC_KEY_free(k);return 1;}

void print_help(void){
    printf("\n  " CLR_BOLD "Byte CLI" CLR_RESET "\n\n");
    printf("  " CLR_CYAN "create" CLR_RESET "                    Criar nova carteira\n");
    printf("  " CLR_CYAN "restore" CLR_RESET "                   Restaurar carteira (12 palavras)\n");
    printf("  " CLR_CYAN "balance" CLR_RESET "                   Ver saldo e stake\n");
    printf("  " CLR_CYAN "send <dest> <qtd>" CLR_RESET "        Enviar moedas (ex: 1.5)\n");
    printf("  " CLR_CYAN "stake <qtd>" CLR_RESET "             Fazer stake (ex: 100.0)\n");
    printf("  " CLR_CYAN "unstake" CLR_RESET "                  Iniciar processo de unstake\n");
    printf("  " CLR_CYAN "peers" CLR_RESET "                    Listar peers conectados\n");
    printf("  " CLR_CYAN "connect <ip/url>" CLR_RESET "        Conectar a peer (TCP/HTTP/HTTPS)\n");
    printf("  " CLR_CYAN "disconnect <ip>" CLR_RESET "         Desconectar peer\n");
    printf("  " CLR_CYAN "mempool" CLR_RESET "                  Ver transações pendentes\n");
    printf("  " CLR_CYAN "mine" CLR_RESET "                     Forçar mineração (se tiver stake)\n");
    printf("  " CLR_CYAN "getblock <altura>" CLR_RESET "       Informações do bloco\n");
    printf("  " CLR_CYAN "status" CLR_RESET "                   Status do node\n");
    printf("  " CLR_CYAN "getinfo" CLR_RESET "                  Informações completas (JSON)\n");
    printf("  " CLR_CYAN "-p <porta>" CLR_RESET "              Porta CMD (padrão: 9334)\n\n");
}

int main(int argc, char **argv) {
    if(argc<2){print_help();return 1;}
    if(strcmp(argv[1],"create")==0){create_wallet("wallet.dat");return 0;}
    if(strcmp(argv[1],"restore")==0){restore_wallet("wallet.dat");return 0;}
    if(strcmp(argv[1],"help")==0||strcmp(argv[1],"--help")==0){print_help();return 0;}

    int port=9334, cmd_start=1;
    for(int i=1;i<argc;i++){if(strcmp(argv[i],"-p")==0&&i+1<argc){port=atoi(argv[i+1]);cmd_start=i+2;break;}}

    if(cmd_start>=argc){printf("Erro: comando necessário\n");return 1;}

    int s=socket(AF_INET,SOCK_STREAM,0);
    struct sockaddr_in a;memset(&a,0,sizeof(a));
    a.sin_family=AF_INET;a.sin_addr.s_addr=inet_addr("127.0.0.1");a.sin_port=htons(port);
    if(connect(s,(struct sockaddr*)&a,sizeof(a))<0){
        printf(CLR_RED "Daemon offline na porta %d\n" CLR_RESET,port);
        return 1;
    }

    char buf[512]={0};

    if(strcmp(argv[cmd_start],"send")==0 && cmd_start+2<argc){
        uint64_t amt=parse_amount(argv[cmd_start+2]);
        snprintf(buf,sizeof(buf),"send %s %llu",argv[cmd_start+1],(unsigned long long)amt);
    }
    else if(strcmp(argv[cmd_start],"stake")==0 && cmd_start+1<argc){
        uint64_t amt=parse_amount(argv[cmd_start+1]);
        snprintf(buf,sizeof(buf),"stake %llu",(unsigned long long)amt);
    }
    else if(strcmp(argv[cmd_start],"connect")==0 && cmd_start+1<argc){
        snprintf(buf,sizeof(buf),"connect %s",argv[cmd_start+1]);
    }
    else if(strcmp(argv[cmd_start],"disconnect")==0 && cmd_start+1<argc){
        snprintf(buf,sizeof(buf),"disconnect %s",argv[cmd_start+1]);
    }
    else if(strcmp(argv[cmd_start],"getblock")==0 && cmd_start+1<argc){
        snprintf(buf,sizeof(buf),"getblock %s",argv[cmd_start+1]);
    }
    else {
        for(int i=cmd_start;i<argc;i++){
            strcat(buf,argv[i]);
            if(i<argc-1) strcat(buf," ");
        }
    }

    send(s,buf,strlen(buf),0);
    char resp[4096];int n=recv(s,resp,sizeof(resp)-1,0);
    if(n>0){resp[n]=0;printf("%s",resp);}
    close(s);
    return 0;
}
